/*
 * A236077  Cubes which remain (integer) cubes when divided by their digital
 *          sum.
 * https://oeis.org/A236077
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  base, nonn
 * Formula:   a(n) is the n-th cube x such that dividing x by its digit sum
 *            yields another integer cube. The values are generated by
 *            scanning all cubes m³ (m ≥ 1) and testing the property
 * Range:     u8 n <= 2, u16 n <= 9, u32 n <= 121, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Validated: standard, pass, 45 terms through n = 9282 (2026-11-03)
 * Helpers:   digit_sum, ipow_i32, mem
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>
#include "../utils/digit_sum.h"
#include "../utils/ipow_i32.h"
#include "../utils/mem.h"

/* Floor cube root by binary search */
static inline seq_t floor_cube_root(seq_t x)
{
    seq_t lo = 0, hi = 1;
    /* raise hi until hi^3 > x */
    while (ipow_i32(hi, 3) <= x)
        hi <<= 1;
    while (lo < hi)
    {
        seq_t mid = (lo + hi) >> 1;
        seq_t mid3 = ipow_i32(mid, 3);
        if (mid3 <= x)
            lo = mid + 1;
        else
            hi = mid;
    }
    return lo - 1;
}

/* Append a value to the cached array, expanding it if necessary.  `p` is a
   pointer to the array pointer. */
static void append_candidate(seq_t **p, size_t *len, size_t *cap, seq_t val)
{
    if (*len == *cap) {
        size_t newcap = (*cap == 0) ? 16 : (*cap << 1);
        seq_t *tmp = mem_resize(seq_t, *p, newcap);
        if (!tmp) {
            exit(EXIT_FAILURE);
        }
        *p = tmp;
        *cap = newcap;
    }
    (*p)[*len] = val;
    (*len)++;
}

static seq_t *terms = NULL;
static size_t terms_len = 0;
static size_t terms_cap = 0;
static idx_t next_m = 1;

static void generate_up_to(idx_t n)
{
    while (terms_len < n) {
        while (true) {
            seq_t m = (seq_t)next_m;
            next_m++;

            seq_t x = m * m * m;          /* m³  */
            seq_t d = digit_sum(x);       /* digit sum of x */

            if (d == 0)
                continue;                 /* digit sum cannot be zero */

            if (x % d != 0)
                continue;                 /* not divisible by its digit sum */

            seq_t y = x / d;
            seq_t k = floor_cube_root(y);

            if (k * k * k == y) {        /* y is a perfect cube */
                append_candidate(&terms, &terms_len, &terms_cap, x);
                break;                    /* next term found */
            }
        }
    }
}

seq_t a(idx_t n)
{
    if (n < 1)
        return 0;                       /* undefined for n == 0 (offset is 1) */

    generate_up_to(n);
    return terms[n - 1];
}
